BEGIN;
ALTER TABLE search_configuration ADD COLUMN fit_instruction text NOT NULL DEFAULT 'Evalúa solo el encaje profesional real entre tareas, autonomía y especialización del anuncio y el perfil acreditado. favorable: tareas compatibles y acceso que admite proyectos, prácticas o primer empleo, o requisitos profesionales acreditados. condicionado: tareas compatibles y un dato concreto de las prácticas podría acreditar un requisito. débil: pide varios años profesionales, autonomía avanzada o especialización que el perfil no acredita, sin suponer excepciones. desconocido: falta evidencia para valorar. No clasifiques A/B/C ni conviertas estudios o proyectos en años profesionales. La cita debe mostrar la condición que justifica el encaje o su brecha; un encaje débil no constituye por sí solo una exclusión.' CHECK(length(trim(fit_instruction)) BETWEEN 1 AND 8000);
COMMIT;
